use Bpt\BptProto;

$tg = BptProto::create(apiId: 123456, apiHash: 'your_api_hash');

// login once (2FA password is the optional 3rd arg)
$tg->client->login('+989120000000', '12345', '2fa_password');

$me = $tg->users->getUsers(['me'])[0];
$tg->messages->sendMessage('me', 'سلام', random_int(1, PHP_INT_MAX));
$tg->messages->sendMessage('@username', 'hi', random_int(1, PHP_INT_MAX));

$history = $tg->messages->getHistory('me', 0, 0, 0, 20, 0, 0);
$contacts = $tg->contacts->getContacts(0);

$tg->session->close();

$tg = BptProto::create(
    apiId: 123456,
    apiHash: 'your_api_hash',
    proxy: 'https://t.me/proxy?server=HOST&port=8443&secret=SECRET', // یا 'socks5://user:pass@127.0.0.1:1080'
    // proxyUser: 'user',  // فقط SOCKS5 با احراز هویت
    // proxyPass: 'pass',
);

// یک‌جا: sendCode → signIn → (در صورت 2FA) checkPassword
$tg->client->login('+989120000000', '12345', '2fa_password');

// یا گام‌به‌گام:
$tg->client->sendCode('+989120000000');       // کد پیامک می‌آید؛ hash ذخیره می‌شود
$tg->client->signIn('+989120000000', '12345'); // اگر SESSION_PASSWORD_NEEDED:
$tg->client->checkPassword('2fa_password');

$tg->messages->sendMessage('me', 'saved', random_int(1, PHP_INT_MAX));
$tg->messages->sendMessage('@durov', 'hi', random_int(1, PHP_INT_MAX));
$tg->messages->sendMessage(['user' => 123, 'access_hash' => 456], 'hi', random_int(1, PHP_INT_MAX));
$tg->channels->joinChannel(['channel' => 789, 'access_hash' => 101112]);

// جواب به یک آپدیت ورودی (peer_type:peer_id):
$tg->messages->sendMessage('user:431927914', 'سلام از BptProto', random_int(1, PHP_INT_MAX));

$tg->on('message', function (array $m) use ($tg): void {
    if (!$m['out']) {
        $tg->messages->sendMessage(
            $m['peer_type'] . ':' . $m['peer_id'],
            'echo: ' . $m['text'],
            random_int(1, PHP_INT_MAX)
        );
    }
}, ['out' => false]);

$tg->run();   // بلاک؛ auto-reconnect — Ctrl+C برای توقف

